#!/usr/bin/env python3
"""Build generic echo appliance only; no SD deployment, invocation or emulator."""
import argparse
import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import time


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--toolchain-bin', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--build-id', default='UNVERSIONED-DO-NOT-DEPLOY',
                        help='Approved fixture identity plus actual UTC build timestamp')
    parser.add_argument('--carrier', choices=('uart','parallel'), default='uart')
    parser.add_argument('--graphics-cycle', action='store_true',
                        help='Independent ordinary mainboard draw/query between echo records')
    parser.add_argument('--rfc25-cycle', action='store_true',
                        help='Independent guarded RFC25 drawing/point reply; parallel only')
    parser.add_argument('--repeat-matrix', action='store_true',
                        help='Separate finite176-record/four-session parallel appliance')
    args = parser.parse_args()
    if args.repeat_matrix and (args.carrier!='parallel' or args.graphics_cycle):
        parser.error('Repeat matrix requires parallel and excludes ordinary graphics variant')
    if args.rfc25_cycle and (args.graphics_cycle or args.carrier!='parallel'):
        parser.error('RFC25 cycle requires parallel carrier and excludes ordinary graphics cycle')
    if not re.fullmatch(r'[A-Za-z0-9-]+', args.build_id):
        parser.error('build ID contains unsupported characters')
    root = Path(__file__).resolve().parents[3]
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    work = output/'work'
    source = work/'src'
    (source/'agon').mkdir(parents=True)
    inputs = {
        'main.cpp':('tests/fixtures/network/repeat.cpp' if args.repeat_matrix else 'tests/fixtures/network/main.cpp'),
        'endpoint.hpp':'tests/fixtures/network/endpoint.hpp',
        'carrier.hpp':'tests/fixtures/network/carrier.hpp',
        'mode_lifecycle.hpp':'tests/fixtures/scroll/mode_lifecycle.hpp',
        'mos_io.asm':'tests/fixtures/controller/mos_io.asm',
        'net_callback.asm':'include/agon/net_callback.asm',
        'agon/net.h':'include/agon/net.h',
    }
    if args.repeat_matrix:
        inputs['repeat_matrix.hpp']='tests/fixtures/network/repeat_matrix.hpp'
    if args.carrier == 'parallel':
        del inputs['net_callback.asm']
        inputs['agon/net_parallel.h']='include/agon/net_parallel.h'
    if args.rfc25_cycle:
        inputs['rfc25_cycle.hpp']='tests/fixtures/network/rfc25_cycle.hpp'
        inputs['rfc25.asm']='tests/fixtures/network/rfc25.asm'
    for name, path in inputs.items():
        shutil.copyfile(root/path, source/name)
    (source/'build_identity.h').write_text(
        '// Generated by the fixture builder; do not edit.\n'
        '#define NETPROBE_BUILD_ID "'+args.build_id+'"\n')
    (work/'Makefile').write_text('NAME=netprobe\nLDHAS_ARG_PROCESSING=1\nLDHAS_EXIT_HANDLER=0\n'
                               'include $(shell agondev-config --makefile)\n'
                               'CXXFLAGS += -Isrc -std=c++17 -fno-exceptions -fno-rtti -Wall -Wextra -Werror\n'+
                               ('CXXFLAGS += -DNETPROBE_PARALLEL=1\n' if args.carrier=='parallel' else ''))
    if args.graphics_cycle:
        with (work/'Makefile').open('a') as file:
            file.write('CXXFLAGS += -DNETPROBE_GRAPHICS_CYCLE=1\n')
    if args.rfc25_cycle:
        with (work/'Makefile').open('a') as file:
            file.write('CXXFLAGS += -DNETPROBE_RFC25_CYCLE=1\n')
    env = dict(os.environ, PATH=str(args.toolchain_bin.resolve())+os.pathsep+os.environ['PATH'])
    start = time.monotonic_ns()
    report = dict(started_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  build_id=args.build_id, status='experimental', carrier=args.carrier,
                  graphics_cycle=args.graphics_cycle,
                  rfc25_cycle=args.rfc25_cycle,
                  repeat_matrix=args.repeat_matrix,
                  source_commit=subprocess.check_output(['git','-C',str(root),'rev-parse','HEAD'],text=True).strip(),
                  scope='native Agon compile/link only; no invocation',
                  inputs={p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in inputs.values()})
    try:
        with (output/'build.log').open('w') as log:
            result = subprocess.run(['make','-j1','-C',str(work)], env=env, stdout=log,
                                    stderr=subprocess.STDOUT, timeout=180)
        report['returncode'] = result.returncode
        if result.returncode:
            raise RuntimeError('Native fixture build failed; see build.log')
        shutil.copyfile(work/'bin/netprobe.bin', output/'netprobe.bin')
        report['binary'] = dict(bytes=(output/'netprobe.bin').stat().st_size,
                               sha256=hashlib.sha256((output/'netprobe.bin').read_bytes()).hexdigest())
    finally:
        report['duration_ns'] = time.monotonic_ns()-start
        report['ended_utc'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        (output/'manifest.json').write_text(json.dumps(report, indent=2)+'\n')
    print(json.dumps(report))


if __name__ == '__main__':
    main()
